import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load mesh from GLB
  const gltf = ctx.glbLoader('/prism-mock/orrery/meshes/gear-a.glb');
  const mesh = gltf.scene.clone();
  group.add(mesh);

  // Apply scene placement transform
  group.position.set(-2.5, -0.2, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // State tracking
  let isHovering = false;
  let hoverTimeline = null;
  let pressTimeline = null;

  const initialY = -0.2;

  // Event handlers
  const handlers = {
    onPointerEnter() {
      if (isHovering) return;
      isHovering = true;

      if (hoverTimeline) hoverTimeline.kill();

      // rise-in: y +0.15, power3.out, 0.7s
      hoverTimeline = gsap.to(group.position, {
        y: initialY + 0.15,
        duration: 0.7,
        ease: 'power3.out'
      });
    },

    onPointerLeave() {
      isHovering = false;

      if (hoverTimeline) hoverTimeline.kill();

      // Settle back to rest position
      hoverTimeline = gsap.to(group.position, {
        y: initialY,
        duration: 0.5,
        ease: 'power2.out'
      });
    },

    onClick() {
      // press-down: scale 0.97, 120ms, back.out
      if (pressTimeline) pressTimeline.kill();

      pressTimeline = gsap.timeline()
        .to(group.scale, {
          x: 0.97,
          y: 0.97,
          z: 0.97,
          duration: 0.12,
          ease: 'back.out'
        }, 0)
        .to(group.scale, {
          x: 1,
          y: 1,
          z: 1,
          duration: 0.2,
          ease: 'back.out'
        });

      // Emit navigation event
      if (config.eventEmitter) {
        config.eventEmitter('hub-home.select', { source: group });
      }
    }
  };

  group.userData.handlers = handlers;
  group.userData.interactive = true;

  // Cleanup resources
  group.userData.cleanup = function() {
    if (hoverTimeline) hoverTimeline.kill();
    if (pressTimeline) pressTimeline.kill();

    mesh.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach(m => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  return group;
}
